mapper.select:
SELECT 
FROM DEFENSE_MODE
WHERE user_id = #{userId}
  AND unavailable_start_date <= #{to}
  AND CASE
          WHEN status = 'RELEASED' THEN return_date
          ELSE expected_return_date
      END >= #{from}
ORDER BY unavailable_start_date ASC, defense_id ASC

mapper.update:
UPDATE DEFENSE_MODE
SET return_date = #{returnDate}, status = #{status}
WHERE defense_id = #{defenseId} AND status = 'ACTIVE'
